### ✅ **`_initMessageListeners` — Scoped with `instanceId`**

```ts
private _initMessageListeners(): void {
  // We'll store the handshake ID for this panel's iframe
  this._instanceId = null;

  const handlers: Record<string, (evt: MessageEvent) => void> = {
    'galyleo:ready': (evt: MessageEvent) => {
      const { instanceId } = evt.data.payload;
      this._instanceId = instanceId;
      console.log(`[Panel] Registered instanceId: ${instanceId}`);

      const dashboardObject = JSON.parse(this._model.toString());
      const payload = {
        instanceId,  // Echo it back to the iframe
        content: dashboardObject
      };
      this._postMessage('galyleo:loadContent', payload);
    },

    'galyleo:contentChanged': (evt: MessageEvent) => {
      const { payload } = evt.data;
      if (!this._isValidInstance(evt)) return;

      this._model.fromJSON(payload.content);
      console.log(`[Panel] Updated model for instanceId: ${this._instanceId}`);
    },

    'galyleo:requestSave': async (evt: MessageEvent) => {
      if (!this._isValidInstance(evt)) return;

      await this._context.save();
      const payload = { instanceId: this._instanceId };
      this._postMessage('galyleo:saveSuccess', payload);
      console.log(`[Panel] Save confirmed for instanceId: ${this._instanceId}`);
    }
  };

  window.addEventListener('message', (evt: MessageEvent) => {
    const { type } = evt.data;
    if (handlers[type]) {
      handlers[type](evt);
    }
  });
}

// Helper: Validate message is for *our* instance
private _isValidInstance(evt: MessageEvent): boolean {
  const { instanceId } = evt.data.payload || {};
  return instanceId && instanceId === this._instanceId;
}

private _postMessage(type: string, payload: any = {}): void {
  this._iframe.contentWindow?.postMessage({ type, payload }, '*');
}
```

---

### 🗝️ **Key improvements**

✅ **Handshake:**  
The Editor sends `galyleo:ready` with `instanceId`.  
We store that `instanceId` in the panel.  
Every outbound message echoes it back.

✅ **Scoped routing:**  
Every message with content checks `instanceId`.  
If it’s not *ours*, we ignore it — so multiple panels never cross-talk.

✅ **Symmetry:**  
The iframe only processes messages that match its `instanceId` — so it stays scoped, too.

✅ **Zero guesswork:**  
No global file path match, no ambiguous overlaps — just simple, reliable isolation.

---

